params.spec:
{
  "$schema": "https://vega.github.io/schema/vega-lite/v6.json",
  "description": "The 10 busiest identities across the top, and down the side the index families they read, busiest first in the same order as Top index families (each family's events from every identity), up to 25; cell colour is audit events on a log scale, teal (fewest) through blue and purple to pink (most), and the line above the matrix says how many of each it shows. A data stream and its backing indices are one family, as is a run of dated daily indices or of per-run indices stamped with a date and time (syn-tmp-20261014-152111-… is syn-tmp*), and system and hidden indices are one family per area (.alerts*, .slo*, .kibana*…), the groups the system-index table names; wildcard and date-math expressions are left out. A blank cell means that identity did not touch that family in range — or touched it too little to be among the 500 busiest identity/family pairs. Events counts a request once per index it names: shard-level copies and the ES|QL engine's per-shard steps name the same indices again and are left out, so it is the same count as Top index families. An identity shown as “_4KEO… · Cloud API key” is an organization-level Elastic Cloud API key, which the audit stream records only by its opaque id. Cells keep a heatmap's size and pack to the top left when only a few identities or families are in range, so a sparse window draws a small matrix with its legend under it, not a few cells adrift in the panel; with three identities or fewer each column widens to fit its label.",
  "title": {
    "text": {
      "expr": "length(data('rows')) ? length(domain('opacity')) + (length(domain('opacity')) == 1 ? ' identity' : ' identities') + ' × ' + length(domain('strokeWidth')) + (length(domain('strokeWidth')) == 1 ? ' index family' : ' index families') + ' shown' : 'No activity for this selection in this time range'"
    }
  },
  "width": "container",
  "height": "container",
  "autosize": {
    "type": "fit",
    "contains": "padding"
  },
  "config": {
    "axis": {
      "labelFontSize": 11,
      "titleFontSize": 11
    },
    "view": {
      "stroke": null
    },
    "title": {
      "fontSize": 12,
      "fontWeight": 500,
      "anchor": "start"
    },
    "legend": {
      "labelFontSize": 11,
      "titleFontSize": 11
    }
  },
  "data": {
    "name": "rows",
    "url": {
      "%type%": "esql",
      "%timefield%": "@timestamp",
      "%context%": true,
      "query": "SET unmapped_fields=\"nullify\"; FROM logs-elastic_cloud.serverless_audit.otel-* | WHERE @timestamp <= ?_tend AND @timestamp > ?_tstart | WHERE elasticsearch.audit.indices IS NOT NULL AND (elasticsearch.audit.action IS NULL OR NOT (elasticsearch.audit.action LIKE \"*[*\" OR elasticsearch.audit.action IN (\"indices:data/read/esql/search_shards\", \"indices:data/read/esql/data\"))) | STATS n = COUNT(*) BY user.email, api_key.name, user.name, elasticsearch.audit.indices | WHERE LOCATE(elasticsearch.audit.indices, \"*\") == 0 AND NOT elasticsearch.audit.indices LIKE \"<*\" | EVAL actor = COALESCE(user.email, api_key.name, user.name, \"<anonymous>\") | EVAL idx = REPLACE(REPLACE(elasticsearch.audit.indices, \"\"\"^\\.ds-\"\"\", \"\"), \"\"\"[-.]?\\d{4}[.-]\\d{2}[.-]\\d{2}(-\\d+)?$\"\"\", \"\") | EVAL idx = REPLACE(idx, \"\"\"[-.]\\d{8}[-.T]?\\d{6}(?:[-.].*)?$\"\"\", \"*\") | EVAL idx = CASE(LEFT(idx, 1) == \".\", CONCAT(REPLACE(idx, \"\"\"^(?:\\.ds-)?(\\.(?:alert-actions|[^-._]+)).*$\"\"\", \"$1\"), \"*\"), idx) | STATS events = SUM(n) BY actor, idx | SORT events DESC | LIMIT 500 | EVAL actor = CASE((LENGTH(actor) == 20 AND actor RLIKE \"[-_A-Za-z0-9]{20}\" AND NOT actor RLIKE \"[0-9]{20}\"), CONCAT(LEFT(actor, 5), \"… · Cloud API key\"), actor)"
    }
  },
  "transform": [
    {
      "joinaggregate": [
        {
          "op": "sum",
          "field": "events",
          "as": "idx_total"
        }
      ],
      "groupby": [
        "idx"
      ]
    },
    {
      "joinaggregate": [
        {
          "op": "sum",
          "field": "events",
          "as": "actor_total"
        }
      ],
      "groupby": [
        "actor"
      ]
    },
    {
      "window": [
        {
          "op": "dense_rank",
          "as": "actor_rank"
        }
      ],
      "sort": [
        {
          "field": "actor_total",
          "order": "descending"
        },
        {
          "field": "actor",
          "order": "ascending"
        }
      ]
    },
    {
      "filter": "datum.actor_rank <= 10"
    },
    {
      "window": [
        {
          "op": "dense_rank",
          "as": "idx_rank"
        }
      ],
      "sort": [
        {
          "field": "idx_total",
          "order": "descending"
        },
        {
          "field": "idx",
          "order": "ascending"
        }
      ]
    },
    {
      "filter": "datum.idx_rank <= 25"
    }
  ],
  "mark": {
    "type": "rect",
    "cornerRadius": 2,
    "width": {
      "expr": "length(domain('opacity')) <= 3 ? bandwidth('x') : min(bandwidth('x'), 64)"
    },
    "height": {
      "expr": "min(bandwidth('y'), 30)"
    }
  },
  "encoding": {
    "y": {
      "field": "idx",
      "type": "nominal",
      "sort": {
        "field": "idx_rank",
        "op": "min",
        "order": "ascending"
      },
      "scale": {
        "paddingInner": 0.1,
        "range": [
          0,
          {
            "expr": "min(height - 48, 34 * length(domain('strokeWidth')))"
          }
        ]
      },
      "axis": {
        "title": null,
        "labelLimit": 280,
        "ticks": false,
        "domain": false,
        "grid": true,
        "bandPosition": 0.5,
        "gridOpacity": 0.35,
        "zindex": 0
      }
    },
    "x": {
      "field": "actor",
      "type": "nominal",
      "sort": {
        "op": "sum",
        "field": "events",
        "order": "descending"
      },
      "scale": {
        "paddingInner": 0.1,
        "range": [
          0,
          {
            "expr": "min(width, (length(domain('opacity')) <= 3 ? 200 : 76) * length(domain('opacity')))"
          }
        ]
      },
      "axis": {
        "title": "Identity",
        "titleOpacity": {
          "expr": "length(data('rows')) ? 1 : 0"
        },
        "orient": "top",
        "labelAngle": {
          "expr": "length(domain('opacity')) <= 3 ? 0 : -90"
        },
        "labelAlign": {
          "expr": "length(domain('opacity')) <= 3 ? 'center' : 'left'"
        },
        "labelBaseline": {
          "expr": "length(domain('opacity')) <= 3 ? 'bottom' : 'middle'"
        },
        "labelLimit": {
          "expr": "length(domain('opacity')) <= 3 ? min(190, bandwidth('x') / 0.9 - 10) : 230"
        },
        "labelPadding": 4,
        "ticks": false,
        "domain": false,
        "grid": true,
        "bandPosition": 0.5,
        "gridOpacity": 0.35,
        "zindex": 0,
        "titlePadding": 8
      }
    },
    "tooltip": [
      {
        "field": "idx",
        "title": "Index family"
      },
      {
        "field": "actor",
        "title": "Identity"
      },
      {
        "field": "events",
        "title": "Events",
        "format": ","
      }
    ],
    "color": {
      "field": "events",
      "type": "quantitative",
      "scale": {
        "type": "log",
        "range": [
          "#54B399",
          "#6092C0",
          "#9170B8",
          "#D36086"
        ],
        "interpolate": "hcl"
      },
      "legend": {
        "title": "Events",
        "orient": "none",
        "direction": "horizontal",
        "gradientLength": 220,
        "gradientThickness": 10,
        "values": {
          "expr": "!(length(data('rows'))) ? [] : floor(log(domain('color')[1]) / LN10 + 1e-9) - ceil(log(domain('color')[0]) / LN10 - 1e-9) >= 1 ? slice([1, 10, 100, 1000, 10000, 100000, 1000000, 10000000, 100000000], ceil(log(domain('color')[0]) / LN10 - 1e-9), 1 + floor(log(domain('color')[1]) / LN10 + 1e-9)) : domain('color')[1] > domain('color')[0] ? domain('color') : [domain('color')[0]]"
        },
        "labelExpr": "format(datum.value, '.2~s')",
        "titleOpacity": {
          "expr": "length(data('rows')) ? 1 : 0"
        },
        "labelOpacity": {
          "expr": "length(data('rows')) ? 1 : 0"
        },
        "gradientOpacity": {
          "expr": "length(data('rows')) ? 1 : 0"
        },
        "legendX": 0,
        "legendY": {
          "expr": "min(height - 48, 34 * length(domain('strokeWidth'))) + 14"
        }
      }
    },
    "opacity": {
      "field": "actor",
      "type": "ordinal",
      "scale": {
        "range": [
          1,
          1
        ]
      },
      "legend": null
    },
    "strokeWidth": {
      "field": "idx",
      "type": "ordinal",
      "scale": {
        "range": [
          0,
          0
        ]
      },
      "legend": null
    }
  }
}
